import numpy as np
import jax.numpy as jnp

# Define the typical values for min_val and max_val to prevent overflow errors
min_val = np.log(np.finfo(np.float32).tiny)
max_val = np.log(np.finfo(np.float32).max)

# Define the custom gradient function for the safe exponential function
def safe_exp_grad(x, _, x_dot):
    return jnp.exp(x) * x_dot

# Define the safe exponential function with safety checks
def safe_exp(x):
    return jnp.exp(jnp.clip(x, min_val, max_val))

# Use jax.grad to generate the safe version of the exponential function with the custom gradient
return jax.grad(safe_exp_grad, has_aux=False)(safe_exp)

